(function(){AppModule.register({routes:[
{path:"compliance/audit",title:"合规与审计",permission:"audit.read",render(){const rows=DB.audits.map(a=>'<tr><td>'+a.time+'</td><td>'+a.actor+'</td><td>'+a.action+'</td><td>'+a.target+'</td><td>'+UI.tag(a.result)+'</td></tr>').join("");return UI.head("合规与审计","追踪授权、个人资源配置变更、项目移交、任务、费用、审核和交付操作。",UI.btn("导出审计记录","export"))+UI.card("最近审计事件",UI.table(["时间","操作者","动作","对象","结果"],rows))+'<div class="grid grid-2" style="margin-top:16px">'+UI.card("合规检查范围",'<div class="list">'+["第三方素材与图像授权","肖像及真人声音克隆授权","音乐、字体和音效授权","模型商业使用条款","生成内容安全检查"].map(x=>'<div class="list-row"><span>'+x+'</span>'+UI.tag("需留档")+'</div>').join("")+'</div>')+UI.card("凭据安全",'<div class="notice warn">审计只记录供应商配置 ID、操作者、变更时间和脱敏摘要，不记录 API Key 明文。运维身份默认不具备业务内容读取权。</div>')+'</div>';}}
]});})();